turn() { : > .tmp/turn.jsonl; jq -cn '{type:"assistant",message:{content:[{type:"tool_use",name:"Skill",input:{skill:"git-workflow"}}]}}' >> .tmp/turn.jsonl; [ -n "$1" ] && jq -cn --arg t "EXAM: passed $1 of 5" '{type:"user",message:{content:[{type:"tool_result",content:$t}]}}' >> .tmp/turn.jsonl; return 0; }
turn 5
fixture_commit "$T" docs/tasks/RT-7-probe/plan.md plan "docs: plan"
mkdir -p libs/x docs/specs/x; printf '# Domain x\n' > docs/specs/x/spec.md; printf 'syntax = 1;\n' > libs/x/a.proto; git add -f libs/x/a.proto
export RT_WINDOW_TOKENS=200000 RT_WINDOW_WARN_PCT=40 RT_WINDOW_STOP_PCT=50
wf_over() { local x="$1" p; p="$(printf '%s' "$x" | jq -r '.transcript_path // empty')"; [ -n "$p" ] || { p="${TMPDIR:-/tmp}/wf-turn.jsonl"; x="$(printf '%s' "$x" | jq -c --arg p "$p" '.transcript_path = $p')"; }; x="$(printf '%s' "$x" | jq -c '.hook_event_name //= "PreToolUse"')"; mkdir -p "$(dirname "$p")"; jq -cn '{type:"assistant",message:{usage:{input_tokens:120000,cache_creation_input_tokens:0,cache_read_input_tokens:0,output_tokens:0}}}' >> "$p"; [ -n "${WF_UNLOAD:-}" ] && for l in "${TMPDIR:-/tmp}"/claude-skill-gate/*.loaded; do [ -f "$l" ] && sed -i.bak '/^task-flow$/d' "$l"; done; printf '%s' "$x"; }
